/** Hears a held row on each frame of the hold, and null at the hand-back. */
export type HeldRowListener = (held: HeldRow | null) => void;

type Attach = (
  element: HTMLElement,
  onHeld?: HeldRowListener,
) => SnapPagingAttachment;

