  value: SnapPaging,
  element: HTMLElement,
  onHeld?: HeldRowListener,
): () => void {
  const attachment = (value as unknown as SnapPagingValue).attach(
    element,
    onHeld,
  );
  attachments.set(element, attachment);
  return () => {
    attachments.delete(element);
    attachment.detach();
  };
