  element: Element | null | undefined,
  leafOrGroup: object,
  key?: string,
): unknown {
  const value =
    key === undefined
      ? leafOrGroup
      : (leafOrGroup as Record<string, unknown>)[key];
  const role =
    key === undefined
      ? motionRoleOf(leafOrGroup)
      : motionRoleIn(leafOrGroup, key);
