    caretPositionFromPoint?: (
      x: number,
      y: number,
      options?: {shadowRoots?: ShadowRoot[]},
    ) => {offsetNode: Node; offset: number} | null;
    caretRangeFromPoint?: (x: number, y: number) => Range | null;
  };
