  ranges: ReadonlyArray<AbstractRange>,
): ReadonlyArray<ShadowRoot> {
  const roots = new Set<ShadowRoot>();
  for (const range of ranges) {
    for (const root of [
      ...openShadowRootsOf(range.startContainer),
      ...openShadowRootsOf(range.endContainer),
    ]) {
      roots.add(root);
    }
